const html: string = "<!doctype html>\n<html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow,noarchive\"><meta name=\"referrer\" content=\"no-referrer\"><title>O.pickle — 会計・在庫を記録</title>\n<style>\n:root{--paper:#f5f4ef;--ink:#171915;--muted:#6d7169;--line:#d7d9d0;--accent:#d6e4b8}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Arial,\"Noto Sans JP\",sans-serif}button,input,select,textarea{font:inherit}button,a,input,select{touch-action:manipulation}button,a{color:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:wait}a{text-decoration:none}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #7d9860;outline-offset:3px}[hidden]{display:none!important}.shell{display:grid;grid-template-columns:300px minmax(0,1fr);min-height:100vh}.rail{background:var(--ink);color:var(--paper);padding:36px 30px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column}.brand{font-size:28px;font-weight:800;letter-spacing:-1.7px}.brand b{font-size:51px;letter-spacing:-6px;margin-right:7px}.eyebrow{font-size:10px;letter-spacing:.17em;line-height:1.8}.rail .eyebrow{color:#a6ac9f;margin-top:18px}.rail h1{font-size:52px;letter-spacing:-3px;line-height:1.02;font-weight:700;margin:65px 0 22px}.rail p{font-size:12px;line-height:2;color:#b7bcb0}.rail .court{height:125px;border:1px solid #747b68;position:relative;margin:32px 0}.court:before{content:'';position:absolute;left:50%;height:100%;border-left:1px solid #747b68}.court:after{content:'';position:absolute;inset:25% 0;border-block:1px solid #747b68}.rail a{margin-top:auto;font-size:12px;padding:16px 0;border-top:1px solid #454a3e}.main{padding:28px clamp(20px,5vw,70px) 70px;max-width:1150px;width:100%}.top{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:24px;font-size:10px;color:var(--muted);gap:12px}.top a{border-bottom:1px solid var(--line);padding-bottom:5px}.intro{padding:36px 0 25px}.intro h2{font-size:clamp(28px,4vw,44px);font-weight:600;letter-spacing:-.06em;margin:10px 0 14px}.intro p,.hint{font-size:12px;color:var(--muted);line-height:1.9;margin:0}.panel{background:#fff;border:1px solid var(--line);padding:26px;margin-bottom:22px}.panel h3{font-size:16px;margin:0 0 20px;letter-spacing:-.04em}.fields{display:grid;grid-template-columns:1fr 1fr;gap:21px}.field{display:flex;flex-direction:column;gap:9px;font-size:12px}.wide{grid-column:1/-1}.field>span{font-weight:600}.field small{font-size:10px;color:var(--muted);line-height:1.7}input,select,textarea{border:1px solid var(--line);border-radius:0;padding:13px;background:var(--paper);min-height:48px;min-width:0;width:100%;color:var(--ink);font-size:15px}textarea{resize:vertical;min-height:90px}input[type=checkbox]{width:20px;min-height:20px;accent-color:var(--ink)}.check{display:flex;align-items:flex-start;gap:11px;font-size:12px;line-height:1.8;margin:22px 0 0}.check input{flex-shrink:0;margin-top:0}.part{display:grid;grid-template-columns:80px 1fr 1fr 45px;gap:10px;align-items:end;margin-bottom:16px}.part label{font-size:10px;display:grid;gap:8px}.part button{width:44px;height:48px;background:transparent;border:1px solid var(--line);font-size:21px}.button{border:1px solid var(--ink);padding:15px 21px;min-height:49px;background:var(--ink);color:#fff;font-size:12px;font-weight:600;display:inline-flex;align-items:center;justify-content:center;gap:18px}.secondary{background:transparent;color:var(--ink)}.actions{display:flex;gap:12px;align-items:center;margin-top:24px;flex-wrap:wrap}.total{border-block:1px solid var(--line);margin:20px 0;padding:18px 0;display:flex;justify-content:space-between;gap:15px;align-items:center;font-size:12px}.total strong{font-size:26px;font-weight:500;letter-spacing:-1px}.total small{font-size:12px;letter-spacing:0}.message{border-left:3px solid #8a694f;background:#eee8df;padding:16px 20px;font-size:12px;line-height:1.9;margin:20px 0;white-space:pre-wrap;overflow-wrap:anywhere}.preview{white-space:pre-wrap;font-size:14px;line-height:2;overflow-wrap:anywhere}.summary{padding:18px;background:var(--paper);font-size:12px;line-height:1.9;white-space:pre-wrap;margin:18px 0}.list{overflow:auto}.list table{border-collapse:collapse;width:100%;min-width:500px;font-size:11px}.list th{text-align:left;color:var(--muted);font-weight:400}.list th,.list td{border-bottom:1px solid var(--line);padding:13px 12px 13px 0;line-height:1.7}.tag{font-size:10px;padding:4px 8px;background:#e8eadf;white-space:nowrap}.note{font-size:10px;color:var(--muted);line-height:1.9;padding-top:20px}.empty{padding:22px 0;font-size:12px;color:var(--muted)}.success-mark{font-size:52px;line-height:1;color:#556945;margin-bottom:24px}.loading{color:var(--muted);font-size:12px;padding:40px 0}.privacy{border-top:1px solid var(--line);margin-top:35px;padding-top:18px;font-size:10px;color:var(--muted);line-height:1.9}.login{max-width:450px;padding:30px 0}.login h2{font-size:38px;letter-spacing:-2px;margin:0 0 20px}.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);border-block:1px solid var(--line);margin-bottom:24px}.stat-grid div{padding:18px 8px;font-size:10px;color:var(--muted)}.stat-grid strong{display:block;font-size:28px;font-weight:500;color:var(--ink);margin-top:10px}.muted{color:var(--muted)}\n#stock-shortcuts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}#stock-shortcuts .button{padding:16px 7px;min-height:64px;font-size:12px}\n@media(max-width:800px){.shell{grid-template-columns:210px 1fr}.rail{padding:28px 23px}.rail h1{font-size:40px}.rail .brand{font-size:23px}.brand b{font-size:42px}.main{padding:25px 25px 50px}.fields{gap:18px}.panel{padding:22px}.part{grid-template-columns:65px 1fr 1fr 40px;gap:7px}.part input{padding:10px 6px}}\n@media(max-width:600px){.shell{display:block}.rail{position:static;height:auto;padding:17px 21px;display:flex;flex-direction:row;align-items:center;justify-content:space-between;gap:18px}.rail .brand{font-size:23px}.rail .brand b{font-size:35px;letter-spacing:-4px}.rail .eyebrow{display:block;margin:0;font-size:8px;text-align:right}.rail h1,.rail p,.rail .court,.rail a{display:none}.main{padding:21px 18px 40px}.top{padding-bottom:18px}.intro{padding-top:27px}.intro h2{font-size:32px}.panel{padding:21px 16px}.fields{grid-template-columns:1fr;gap:19px}.wide{grid-column:auto}.part{grid-template-columns:60px 1fr 1fr 37px;gap:6px}.part button{width:37px}.part input{font-size:14px}.total strong{font-size:23px}.actions .button{flex:1}.stat-grid strong{font-size:25px}}\n</style><style>\n.photo-editor{border:1px solid var(--line);padding:20px;min-width:0}.photo-editor h4{margin:0 0 7px;font-size:15px}.photo-editor p{font-size:12px;color:#64645e;line-height:1.8}.photo-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:14px 0}.photo-cell{min-width:0}.photo-thumb{padding:0;border:1px solid var(--line);background:#eeede7;display:block;width:100%;cursor:zoom-in}.photo-thumb img{width:100%;height:145px;object-fit:contain;display:block}.photo-remove{margin-top:7px;width:100%;font-size:11px;padding:8px;border:1px solid var(--line);background:white;cursor:pointer}.photo-editor input[type=file]{max-width:100%;font-size:12px}.photo-status{min-height:20px}.photo-preset{display:flex;align-items:center;gap:12px;padding:10px;border:1px solid var(--line);background:#f6f5ef;text-align:left;cursor:pointer;width:100%;margin:12px 0}.photo-preset img{width:90px;height:60px;object-fit:contain;background:#222}.product-photo-card{padding:18px 0;border-bottom:1px solid var(--line)}.product-photo-card h4{margin:0}.product-photo-card .photo-grid{max-width:660px}.photo-dialog{border:0;background:#f6f5f0;padding:12px;max-width:min(94vw,1100px);max-height:94vh}.photo-dialog::backdrop{background:#000c}.photo-dialog img{display:block;max-width:100%;max-height:78vh;object-fit:contain}.photo-dialog button{display:block;margin-left:auto;margin-bottom:10px;padding:10px 18px;border:1px solid #222;background:white;cursor:pointer}@media(max-width:600px){.photo-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.photo-thumb img{height:130px}.photo-editor{padding:14px}.photo-preset img{width:70px}}\n</style></head><body>\n<div class=\"shell\"><aside class=\"rail\"><div class=\"brand\"><b>O.</b>pickle</div><div class=\"eyebrow\">COMMUNITY OPERATIONS<br>ACCOUNTING & INVENTORY</div><h1>LESS<br>ADMIN.<br>MORE<br>PLAY.</h1><p>次の一日を、気持ちよく。<br>予約と会計、商品と在庫を<br>ひとつずつ、確実に。</p><div class=\"court\" aria-hidden=\"true\"></div><a href=\"/opickle/accounting\">会計ダッシュボードへ ↗</a></aside>\n<main class=\"main\"><nav class=\"top\"><span>O.PICKLE / OPERATIONS</span><a href=\"https://chat.google.com/app/chat/AAQAjlXBeJ0\">Google Chatに戻る ↗</a></nav>\n<div id=\"loading\" class=\"loading\" role=\"status\">接続を確認しています…</div><div id=\"error\" class=\"message\" role=\"alert\" hidden></div>\n<section id=\"login\" class=\"login\" hidden><h2>WELCOME<br>BACK.</h2><p class=\"hint\">会計ページと同じパスワードで開けます。</p><form id=\"login-form\"><label class=\"field\" style=\"margin-top:25px\"><span>パスワード</span><input id=\"password\" type=\"password\" autocomplete=\"current-password\" required maxlength=\"128\"></label><div class=\"actions\"><button class=\"button\" type=\"submit\">フォームを開く →</button></div></form></section>\n<section id=\"content\" hidden><header class=\"intro\"><span class=\"eyebrow\" id=\"mode-label\"></span><h2 id=\"title\"></h2><p id=\"description\"></p></header>\n<form id=\"entry-form\">\n<section id=\"reservation\" hidden><div class=\"panel\"><h3>01 / 開催と支払い</h3><div class=\"fields\"><label class=\"field\"><span>開催日</span><input id=\"reserve-day\" type=\"date\" min=\"2026-10-21\"></label><label class=\"field\"><span>コート名・会場名</span><input id=\"venue\" type=\"text\" maxlength=\"80\" placeholder=\"例：Picks & Rec\"></label><label class=\"field\"><span>コート代の支払日</span><input id=\"paid-day\" type=\"date\" min=\"2026-10-21\"></label><label class=\"field\"><span>支払済みの合計 / RM</span><input id=\"cost\" type=\"number\" min=\"0.01\" max=\"1000000\" step=\"0.01\" inputmode=\"decimal\" placeholder=\"350.00\"></label></div></div><div class=\"panel\"><h3>02 / 予約の内訳</h3><p class=\"hint\">時間が違う予約は、行を追加してください。<br>例：3面 9:00–12:00 ＋ 1面 12:00–13:00</p><div id=\"parts\" style=\"margin-top:22px\"></div><button id=\"add-part\" class=\"button secondary\" type=\"button\">＋ 予約枠を追加</button><div class=\"total\"><span>総予約時間</span><strong id=\"total-hours\">— <small>面時間</small></strong></div><p class=\"hint\">面数×時間を合計します。同じ会場の追加予約もここへ。別会場は別の予約として登録してください。</p><label class=\"check\"><input type=\"checkbox\" id=\"reserve-paid\"><span>妻のTouch 'n Goから、上記の金額を支払い済みです。参加費は開催後に別途確定します。</span></label></div></section>\n<section id=\"settlement\" hidden><div class=\"panel\"><h3>01 / 予約を選択</h3><label class=\"field\"><span>開催日・会場</span><select id=\"booking\"></select></label><div id=\"booking-detail\" class=\"summary\" hidden></div><div class=\"fields\"><label class=\"field wide\"><span>今回の報告</span><select id=\"settle-operation\"><option value=\"final\">最終人数・参加費を報告</option><option value=\"receipt\">報告後に追加で受け取った参加費</option><option value=\"court_refund\">施設から受け取ったコート代の返金</option></select></label><label class=\"field\" id=\"count-field\"><span>最終参加人数（主催者を含む）</span><input id=\"people\" type=\"number\" min=\"1\" max=\"10000\" step=\"1\" inputmode=\"numeric\"></label><label class=\"field\" id=\"unit-field\"><span>1人あたりの参加費 / RM</span><input id=\"participation-unit\" aria-label=\"1人あたりの参加費 / RM\" type=\"number\" min=\"0.01\" max=\"1000000\" step=\"0.01\" inputmode=\"decimal\" value=\"25\"><small>通常はRM25。大会などは今回の単価に変更できます。</small></label></div><div class=\"total\" id=\"expected-box\"><span>人数 × 1人あたりの参加費</span><strong id=\"expected\">—</strong></div><div id=\"full-income-action\"><button type=\"button\" id=\"full-income\" class=\"button secondary\">全額受取済み → 合計を入金額に入力</button><p class=\"hint\" style=\"margin-top:10px\">まだ受け取っていない分は含めず、一部入金なら下の金額を入力してください。</p></div><div class=\"fields\" style=\"margin-top:22px\"><label class=\"field\"><span>今回、実際に受け取った金額 / RM</span><input id=\"income\" type=\"number\" min=\"0\" max=\"1000000\" step=\"0.01\" inputmode=\"decimal\"></label><label class=\"field\"><span>入金日・最終受取日</span><input id=\"received-day\" type=\"date\" min=\"2026-10-21\"></label></div><label class=\"check\" id=\"cancelled-field\"><input id=\"event-cancelled\" type=\"checkbox\"><span>開催を中止しました。人数報告を完了し、支払済コート代は残します。</span></label><label class=\"check\"><input id=\"income-confirmed\" type=\"checkbox\"><span>予定額ではなく、妻のTouch 'n Goで実際に受け取った金額を確認しました。今回の金額だけを記録します。</span></label><p class=\"note\">終了10分前の案内から入力を準備できます。最終人数は開催終了後に確定してください。支払済みのコート代は再計上しません。</p></div><div class=\"panel\"><h3>報告状況</h3><div id=\"booking-stats\" class=\"stat-grid\"></div><div id=\"booking-list\" class=\"list\"></div></div></section>\n<section id=\"expense\" hidden><div class=\"panel\"><h3>購入・支払いの記録</h3><div class=\"fields\"><label class=\"field\"><span>支払日</span><input id=\"expense-day\" type=\"date\" min=\"2026-10-21\"></label><label class=\"field\"><span>費目</span><select id=\"expense-category\"><option>物品費</option><option>その他経費</option></select></label><label class=\"field wide\"><span>購入先・支払先</span><input id=\"merchant\" type=\"text\" maxlength=\"80\" placeholder=\"例：Shopee\"></label><label class=\"field wide\"><span>購入したもの・支払いの内容</span><textarea id=\"expense-description\" maxlength=\"200\" placeholder=\"例：練習用ボール 12個\"></textarea></label><label class=\"field\"><span>支払済金額 / RM</span><input id=\"expense-amount\" type=\"number\" min=\"0.01\" max=\"1000000\" step=\"0.01\" inputmode=\"decimal\"></label></div><label class=\"check\"><input id=\"expense-paid\" type=\"checkbox\"><span>妻のTouch 'n Goから支払い済みです。在庫の入荷フォームで購入費を記録したものは、ここへ重複入力していません。</span></label></div></section>\n<section id=\"inventory\" hidden><div class=\"panel\"><h3>何がありましたか？</h3><div class=\"actions\" id=\"stock-shortcuts\" style=\"margin:0 0 22px\"><button type=\"button\" class=\"button\" data-stock-action=\"new_product\">新しい商品</button><button type=\"button\" class=\"button secondary\" data-stock-action=\"purchase\">仕入れた</button><button type=\"button\" class=\"button secondary\" data-stock-action=\"sale\">売れた</button></div><label class=\"field\"><span>入力する内容・その他の管理</span><select id=\"stock-action\"><option value=\"new_product\">新しい商品ができた（商品と個数をまとめて登録）</option><option value=\"purchase\">仕入れた（商品を選ぶ・なければ登録）</option><option value=\"sale\">売れた（注文・受け渡し・入金）</option><optgroup label=\"後からの報告・その他の管理\"><option value=\"opening\">登録済み商品の初期在庫を登録</option><option value=\"deliver\">後から商品を渡した</option><option value=\"receive\">後から代金を受け取った</option><option value=\"transfer\">保管者間で在庫を移動</option><option value=\"adjust\">現物を数えて在庫数を訂正</option><option value=\"return\">返品を受け取った</option><option value=\"refund\">返品分の代金を返金した</option><option value=\"cancel\">未受渡し・未入金の注文を取消</option><option value=\"holder\">保管者を追加</option></optgroup></select></label><div id=\"stock-fields\" class=\"fields\" style=\"margin-top:24px\"></div><div id=\"stock-context\" class=\"summary\" hidden></div><label class=\"check\"><input id=\"stock-confirmed\" type=\"checkbox\"><span>現物の個数と、今回の受け渡し・実際の入出金を確認しました。</span></label></div><div class=\"panel\"><h3>保管者ごとの在庫</h3><p class=\"hint\">現物在庫と、注文のために確保した数を分けて表示します。</p><div id=\"stock-list\" class=\"list\"></div></div><div class=\"panel\"><h3>販売・受け渡し・入金</h3><div id=\"sales-list\" class=\"list\"></div></div></section>\n<div class=\"actions\"><button id=\"preview-button\" class=\"button\" type=\"submit\">内容を確認する →</button></div></form>\n<section id=\"confirmation\" class=\"panel\" hidden><h3>この内容で記録します</h3><div id=\"preview-text\" class=\"preview\"></div><p class=\"note\">ここではまだ記録していません。内容を確認してから確定してください。</p><div class=\"actions\"><button id=\"edit\" class=\"button secondary\" type=\"button\">入力に戻る</button><button id=\"commit\" class=\"button\" type=\"button\">確定して記録する →</button></div></section>\n<section id=\"success\" class=\"panel\" hidden><div class=\"success-mark\" aria-hidden=\"true\">✓</div><h3>記録しました</h3><div id=\"success-text\" class=\"preview\"></div><p class=\"note\" id=\"notification-note\"></p><div class=\"actions\"><a class=\"button\" href=\"https://chat.google.com/app/chat/AAQAjlXBeJ0\">Google Chatに戻る ↗</a><a class=\"button secondary\" href=\"/opickle/accounting\">残高を見る →</a></div></section>\n</section><footer class=\"privacy\">この入力リンクはGoogle Chatから発行され、有効期限は90分です。次の入力はChatで「予約」「精算」「経費」「在庫」と送って始めてください。<br>時刻・日付はマレーシア時間。口座は妻TNG。商品在庫の数量や評価額は、運営資金の残高に加算しません。</footer></main></div>\n<script>\n(()=>{'use strict';\nconst $=id=>document.getElementById(id),API='/api/opickle/accounting',params=new URLSearchParams(location.hash.slice(1));const ticketKey='opickle_private_form_ticket';let token=params.get('ticket')||'',state=null,nonce=null,busy=false;try{if(token)sessionStorage.setItem(ticketKey,JSON.stringify({token,at:Date.now()}));else{const old=JSON.parse(sessionStorage.getItem(ticketKey)||'null');if(old&&Date.now()-old.at<90*60000)token=old.token;else sessionStorage.removeItem(ticketKey);}}catch{}history.replaceState(null,'',location.pathname);const text=(id,value)=>$(id).textContent=value,rm=n=>'RM'+Number(n).toFixed(2);const day=id=>$(id).value.replaceAll('-','/'),number=id=>{const raw=$(id).value;if(!raw.trim())throw Error('未入力の項目を確認してください。');const n=Number(raw);if(!Number.isFinite(n))throw Error('数字を確認してください。');return n;};\nfunction error(e){text('error',String(e.message||e));$('error').hidden=false;$('error').scrollIntoView({block:'nearest',behavior:'smooth'});}function clearError(){$('error').hidden=true;}function lock(value){busy=value;for(const e of document.querySelectorAll('button'))e.disabled=value;}\nasync function request(action,data){const payload={token,...data};const r=await fetch(API+'/form',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,payload})});let result;try{result=await r.json();}catch{throw Error('接続を確認できません。入力内容はそのままで、再度お試しください。');}if(r.status===401){$('content').hidden=true;$('login').hidden=false;throw Error('会計ページのパスワードを入力してください。');}if(!r.ok)throw Error(r.status===429?'操作が集中しています。少し待って再度お試しください。':'接続を確認できません。同じ画面から再試行してください。');if(!result.ok)throw Error(result.error||'内容を確認してください。');return result;}\nfunction option(select,value,label){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o);}function table(root,headers,rows){root.replaceChildren();if(!rows.length){const p=document.createElement('p');p.className='empty';p.textContent='まだ記録はありません。';root.append(p);return;}const t=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');for(const h of headers){const e=document.createElement('th');e.textContent=h;tr.append(e);}head.append(tr);t.append(head);const body=document.createElement('tbody');for(const row of rows){const tr=document.createElement('tr');for(const value of row){const td=document.createElement('td');td.textContent=String(value??'');tr.append(td);}body.append(tr);}t.append(body);root.append(t);}\nfunction addPart(){if($('parts').children.length>=20)return;const row=document.createElement('div');row.className='part';for(const [label,type,value,key]of [['面数','number','1','count'],['開始','time','09:00','start'],['終了','time','12:00','end']]){const l=document.createElement('label');l.textContent=label;const i=document.createElement('input');i.type=type;i.value=value;i.dataset.part=key;i.required=true;if(type==='number'){i.min='1';i.max='50';i.step='1';i.inputMode='numeric';}i.addEventListener('input',totals);l.append(i);row.append(l);}const b=document.createElement('button');b.type='button';b.textContent='×';b.setAttribute('aria-label','この予約枠を削除');b.addEventListener('click',()=>{row.remove();totals();});row.append(b);$('parts').append(row);totals();}\nfunction parts(){return [...$('parts').children].map(row=>{const get=k=>row.querySelector('[data-part=\"'+k+'\"]').value;const minutes=s=>{const [h,m]=s.split(':').map(Number);return h*60+m;};return{count:Number(get('count')),start:minutes(get('start')),end:minutes(get('end'))};});}function totals(){const p=parts(),valid=p.length&&p.every(p=>Number.isInteger(p.count)&&p.count>0&&Number.isFinite(p.start)&&p.end>p.start);$('total-hours').replaceChildren(document.createTextNode(valid?String(p.reduce((n,p)=>n+p.count*(p.end-p.start),0)/60):'—'));const small=document.createElement('small');small.textContent=' 面時間';$('total-hours').append(small);}\nfunction bookingDetail(){const b=state.bookings.find(b=>b.id===$('booking').value);$('booking-detail').hidden=!b;if(!b)return;const clock=m=>Math.floor(m/60)+':'+String(m%60).padStart(2,'0');text('booking-detail',b.id+' / '+b.day+' / '+b.venue+'\\n'+b.parts.map(p=>p.count+'面 '+clock(p.start)+'–'+clock(p.end)).join(' ＋ ')+'\\n総予約時間 '+b.hours+'面時間 / 支払済 '+rm(b.cost)+'\\n'+b.status+(b.settlement?' / 参加'+b.settlement.count+'人 × '+rm(b.settlement.unit??25)+' / 入金合計'+rm(b.settlement.income):''));}\nfunction updateExpected(){const qty=Number($('people').value),unit=Number($('participation-unit').value);text('expected',qty>0&&unit>0?rm(qty*Math.round(unit*100)/100):'—');}\nfunction settlementOperation(){const final=$('settle-operation').value==='final';for(const id of ['count-field','unit-field','expected-box','cancelled-field','full-income-action'])$(id).hidden=!final;if(!final)$('event-cancelled').checked=false;const cancelled=final&&$('event-cancelled').checked;for(const id of ['people','participation-unit','income','full-income'])$(id).disabled=cancelled;}\nfunction fillBookings(){const select=$('booking');select.replaceChildren();for(const b of [...state.bookings].reverse())option(select,b.id,b.day+' '+b.venue+' / '+b.status);if(state.selected)select.value=state.selected;bookingDetail();table($('booking-list'),['開催日','会場','コート代','状況'],[...state.bookings].reverse().map(b=>[b.day,b.venue,rm(b.cost),b.status]));const stats=$('booking-stats');stats.replaceChildren();for(const label of ['開催前','報告待ち','報告済み']){const e=document.createElement('div');e.textContent=label;const strong=document.createElement('strong');strong.textContent=state.bookings.filter(b=>b.status.startsWith(label)).length;e.append(strong);stats.append(e);}}\nconst stockSchema={product:[['name','商品名','text'],['color','色','text'],['size','サイズ','text'],['unitPrice','標準販売単価 / RM','money']],holder:[['name','保管者名','text']],opening:[['sku','商品・色・サイズ','product'],['holder','保管者','holder'],['qty','いま保管している個数','qty'],['day','確認日','date'],['note','確認内容・メモ','text']],stock:[['sku','商品・色・サイズ','product'],['holder','保管者','holder'],['qty','入荷した個数','qty'],['day','入荷・支払日','date'],['note','購入先・内容','text'],['amount','今回支払済みの購入費 / RM（未払いは0）','money']],transfer:[['sku','商品・色・サイズ','product'],['from','保管元','holder'],['to','移動先','holder'],['qty','実際に移動した個数','qty'],['day','移動日','date']],sale:[['sku','商品・色・サイズ','product'],['holder','取り置きする保管者','holder'],['customer','購入者名','text'],['qty','注文個数','qty'],['unitPrice','今回の販売単価 / RM','money'],['day','販売・注文日','date']],deliver:[['saleId','販売記録','sale'],['qty','今回渡した個数','qty'],['day','受渡し日','date']],receive:[['saleId','販売記録','sale'],['amount','今回受取済みの金額 / RM','money'],['day','受取日','date']],cancel:[['saleId','販売記録','sale'],['day','取消日','date']],return:[['saleId','販売記録','sale'],['holder','返品を保管する人','holder'],['qty','今回受け取った返品個数','qty'],['day','返品受取日','date']],refund:[['saleId','販売記録','sale'],['amount','今回返金済みの金額 / RM','money'],['day','返金日','date']]};\nstockSchema.purchase=[['day','入荷・支払日','date'],['note','購入先・請求の内容','text'],['amount','この請求全体で支払済みの総額 / RM（未払いは0）','money']];stockSchema.adjust=[['sku','商品・色・サイズ','product'],['holder','保管者','holder'],['qty','数え直した現物の個数','zeroqty'],['day','棚卸日','date'],['note','訂正の理由（必須）','text']];\nstockSchema.new_product=[['name','商品名','text'],['color','色','text'],['size','サイズ','text'],['unitPrice','標準販売単価 / RM','money'],['qty','登録する個数（まだない場合は0）','zeroqty'],['holder','保管者','holder'],['day','登録・入荷日','date'],['stockType','個数の登録方法','stockType'],['amount','今回支払済みの仕入総額 / RM（未払いは0）','money']];\nstockSchema.sale=[['sku','商品を選ぶ','product'],['holder','商品を保管している人','holder'],['customer','購入者名','text'],['qty','売れた個数・注文個数','qty'],['unitPrice','1個あたりの販売価格 / RM','money'],['day','販売・注文日','date'],['delivered','今回渡した個数（まだなら0）','zeroqty'],['received','今回受取済みの金額 / RM（未入金は0）','money']];\nlet purchaseLineSequence=0;\nconst photoGroups=new Map(),photoUploads=new Set(),validPhoto=id=>typeof id==='string'&&/^[a-f0-9]{64}$/.test(id);\nstockSchema.photos=[['sku','写真を変更する商品','product']];option($('stock-action'),'photos','商品写真を追加・変更');\nfunction photoThumb(id,label){\n const button=document.createElement('button');button.type='button';button.className='photo-thumb';button.setAttribute('aria-label',label+'を拡大');const img=document.createElement('img');img.src=API+'/photo/'+id;img.alt=label;img.loading='lazy';button.append(img);\n button.addEventListener('click',()=>{const dialog=document.createElement('dialog');dialog.className='photo-dialog';dialog.setAttribute('aria-label',label);const close=document.createElement('button');close.type='button';close.textContent='閉じる';close.addEventListener('click',()=>dialog.close());const large=document.createElement('img');large.src=API+'/photo/'+id;large.alt=label;dialog.append(close,large);dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal();});return button;\n}\nfunction photoValues(id){return [...(photoGroups.get(id)?.images||[])];}\nasync function photoData(file){\n if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12000000)throw Error('写真はJPEG・PNG・WebPで、1枚12MB以内のものを選んでください。');\n const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});try{const ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.86));if(blob&&blob.size>1400000)blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.72));if(!blob||blob.size>1400000)throw Error('写真が大きいため、小さくして選び直してください。');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('写真を読み込めませんでした。'));reader.readAsDataURL(blob);});}finally{bitmap.close();}\n}\nfunction photoPicker(id,initial=[]){\n const previous=photoGroups.get(id);if(previous?.controller)previous.controller.abort();\n const box=document.createElement('div');box.id=id;box.className='photo-editor wide';const group={images:initial.filter(validPhoto).slice(0,4),controller:null};photoGroups.set(id,group);\n const heading=document.createElement('h4');heading.textContent='商品写真（最大4枚）';const note=document.createElement('p');note.textContent='JPEG・PNG・WebP。写真を選ぶと保存しやすい大きさに調整します。商品の確定前に追加・削除できます。';const grid=document.createElement('div');grid.className='photo-grid';const input=document.createElement('input');input.type='file';input.multiple=true;input.accept='image/jpeg,image/png,image/webp';input.setAttribute('aria-label','商品写真を選ぶ（最大4枚）');const status=document.createElement('p');status.className='photo-status';status.setAttribute('role','status');\n const render=()=>{grid.replaceChildren();group.images.forEach((image,n)=>{const cell=document.createElement('div');cell.className='photo-cell';cell.append(photoThumb(image,'商品写真 '+(n+1)));const remove=document.createElement('button');remove.type='button';remove.className='photo-remove';remove.textContent='写真'+(n+1)+'を削除';remove.addEventListener('click',()=>{if(busy||group.controller)return;group.images.splice(n,1);render();});cell.append(remove);grid.append(cell);});input.disabled=group.images.length>=4||!!group.controller;status.textContent=group.controller?'写真を保存しています…':group.images.length+' / 4枚';};\n box.append(heading,note,grid,input,status);\n for(const preset of state.imagePresets||[]){const button=document.createElement('button');button.type='button';button.className='photo-preset';const cover=document.createElement('img');cover.src=API+'/photo/'+preset.images[0];cover.alt=preset.name;const label=document.createElement('span');label.textContent=preset.name+'の画像を追加';button.append(cover,label);button.addEventListener('click',()=>{if(busy||group.controller){error(Error('写真の保存や確認が終わってから操作してください。'));return;}const next=[...new Set([...group.images,...preset.images.filter(validPhoto)])];if(next.length>4){error(Error('商品写真は4枚までです。先に不要な写真を削除してください。'));return;}group.images=next;const name=$(id==='stock-images'?'stock-name':id.replace(/images$/,'name'));if(name&&!name.value.trim())name.value=preset.name;render();});box.append(button);}\n input.addEventListener('change',async()=>{const files=[...input.files];input.value='';if(busy||group.controller){error(Error('写真の保存や確認が終わってから選んでください。'));return;}if(files.length+group.images.length>4){error(Error('商品写真は4枚までです。選ぶ枚数を減らしてください。'));return;}if(!files.length)return;clearError();const controller=new AbortController();group.controller=controller;photoUploads.add(controller);render();try{for(const file of files){const image=await photoData(file);if(controller.signal.aborted||photoGroups.get(id)!==group)break;const response=await fetch(API+'/photo',{method:'POST',credentials:'same-origin',cache:'no-store',signal:controller.signal,headers:{'Content-Type':'application/json'},body:JSON.stringify({token,image})});const result=await response.json();if(!response.ok||!result.ok){if(response.status===401){$('content').hidden=true;$('login').hidden=false;}throw Error(response.status===429?'写真の保存が集中しています。少し待って再度選んでください。':response.status===507?'写真の保存領域がいっぱいです。管理者に確認してください。':'写真を保存できませんでした。JPEG・PNG・WebPの写真を選び直してください。');}if(!validPhoto(result.image?.id))throw Error('写真を確認できませんでした。');if(photoGroups.get(id)===group&&!group.images.includes(result.image.id)&&group.images.length<4)group.images.push(result.image.id);}}catch(e){if(e.name!=='AbortError'&&photoGroups.get(id)===group)error(e);}finally{photoUploads.delete(controller);group.controller=null;if(photoGroups.get(id)===group)render();}});render();return box;\n}\nfunction stockInput(id,label,type,value=''){\n const l=document.createElement('label');l.className='field';l.id=id+'-field';const span=document.createElement('span');span.textContent=label;l.append(span);let e;\n if(['holder','sale','stockType'].includes(type)){\n  e=document.createElement('select');if(type==='holder')for(const h of state.holders)option(e,h.id,h.name);if(type==='sale')for(const v of state.sales.filter(v=>!v.cancelled))option(e,v.id,v.id+' / '+v.customer+' / '+v.status);\n  if(type==='stockType'){option(e,'opening','既にある在庫を登録（過去の購入費は追加しない）');option(e,'purchase','今回仕入れた商品（今回の支払額も記録）');}\n }else{\n  e=document.createElement('input');e.type=type==='date'?'date':['money','qty','zeroqty'].includes(type)?'number':'text';\n  if(type==='date'){e.value=state.today;e.min='2026-10-21';e.max=state.today;}else if(['money','qty','zeroqty'].includes(type)){e.min=type==='qty'?'1':'0';e.max=type==='money'?'1000000':'10000';e.step=type==='money'?'0.01':'1';e.inputMode=type==='money'?'decimal':'numeric';e.value=value||(['money','zeroqty'].includes(type)?'0':'1');}else e.maxLength=id.includes('note')?'200':'80';\n }\n e.id=id;e.setAttribute('aria-label',label);e.required=true;e.addEventListener('input',stockContext);e.addEventListener('change',stockContext);l.append(e);return l;\n}\nfunction productPicker(id,label,withQty=false){\n const box=document.createElement('div');box.className='wide';const l=document.createElement('label');l.className='field';const span=document.createElement('span');span.textContent=label;l.append(span);const e=document.createElement('select');e.id=id;e.setAttribute('aria-label',label);e.required=true;option(e,'','商品を選んでください');for(const p of state.products)option(e,p.id,p.name+' / '+p.color+' / '+p.size);option(e,'__new__','＋ 一覧にない商品を登録する');l.append(e);box.append(l);\n const free=document.createElement('div');free.className='fields';free.id=id+'-new';free.style.marginTop='18px';\n for(const [key,label,type]of [['name','新しい商品名','text'],['color','新しい商品の色','text'],['size','新しい商品のサイズ','text'],...(withQty?[['qty','販売前の現物在庫数（今回売る分を含む）','qty']]:[['unitPrice','新しい商品の標準販売単価 / RM','money']])])free.append(stockInput(id+'-new-'+key,label,type));free.append(photoPicker(id+'-new-images'));box.append(free);\n const update=()=>{free.hidden=e.value!=='__new__';for(const input of free.querySelectorAll('input'))input.disabled=free.hidden;if(id==='stock-sku'&&e.value!=='__new__'){const p=state.products.find(p=>p.id===e.value);if(p&&$('stock-unitPrice'))$('stock-unitPrice').value=String(p.unitPrice);}stockContext();};\n e.addEventListener('change',update);if(!state.products.length)e.value='__new__';free.hidden=e.value!=='__new__';for(const input of free.querySelectorAll('input'))input.disabled=free.hidden;return box;\n}\nfunction selectedProduct(id,withQty=false){\n if($(id).value!=='__new__')return {sku:$(id).value};\n const p={name:$(id+'-new-name').value,color:$(id+'-new-color').value,size:$(id+'-new-size').value,unitPrice:withQty?number('stock-unitPrice'):number(id+'-new-unitPrice'),images:photoValues(id+'-new-images')};if(withQty)p.qty=number(id+'-new-qty');return {newProduct:p};\n}\nfunction addPurchaseLine(){\n const root=$('purchase-lines');if(root.children.length>=20)return;const row=document.createElement('div');row.className='fields';row.id='purchase-row-'+(++purchaseLineSequence);row.style.cssText='padding:20px 0;border-top:1px solid var(--line);gap:18px';row.append(productPicker(row.id+'-sku','商品を選ぶ'));row.append(stockInput(row.id+'-holder','保管者','holder'));row.append(stockInput(row.id+'-qty','入荷した個数','qty'));const b=document.createElement('button');b.type='button';b.className='button secondary';b.textContent='この商品行を削除';b.addEventListener('click',()=>row.remove());row.append(b);root.append(row);\n}\nfunction stockFields(){\n for(const group of photoGroups.values())group.controller?.abort();photoGroups.clear();\n const action=$('stock-action').value,root=$('stock-fields');root.replaceChildren();$('stock-confirmed').checked=false;\n for(const button of document.querySelectorAll('[data-stock-action]')){const selected=button.dataset.stockAction===action;button.classList.toggle('secondary',!selected);button.setAttribute('aria-pressed',String(selected));}\n if(action==='purchase'){\n  const box=document.createElement('div');box.className='wide';box.id='purchase-lines';root.append(box);addPurchaseLine();const b=document.createElement('button');b.type='button';b.className='button secondary wide';b.textContent='＋ 同じ請求の商品行を追加';b.addEventListener('click',addPurchaseLine);root.append(b);\n }\n for(const [key,label,type]of stockSchema[action]){\n  if(type==='product'){if(action==='sale')root.append(productPicker('stock-sku',label,true));else{const l=stockInput('stock-sku',label,'holder');const e=l.querySelector('select');e.replaceChildren();option(e,'','商品を選んでください');for(const p of state.products)option(e,p.id,p.name+' / '+p.color+' / '+p.size);root.append(l);}continue;}\n  const l=stockInput('stock-'+key,label,type);if(key==='note')l.querySelector('input').required=['purchase','adjust'].includes(action);root.append(l);if(key==='unitPrice'&&['product','new_product'].includes(action))root.append(photoPicker('stock-images'));\n }\n if(action==='photos'){\n  root.append(photoPicker('stock-images'));$('stock-sku').addEventListener('change',()=>{const p=state.products.find(p=>p.id===$('stock-sku').value);$('stock-images').replaceWith(photoPicker('stock-images',p?.images||[]));});\n }\n if(action==='sale'){\n  const total=document.createElement('div');total.className='total wide';const label=document.createElement('span');label.textContent='個数 × 1個あたりの販売価格';const value=document.createElement('strong');value.id='sale-total';total.append(label,value);root.append(total);\n  const quick=document.createElement('button');quick.type='button';quick.className='button secondary wide';quick.textContent='全て渡して全額受取済み';quick.addEventListener('click',()=>{const qty=number('stock-qty'),price=number('stock-unitPrice');$('stock-delivered').value=String(qty);$('stock-received').value=String(qty*Math.round(price*100)/100);stockContext();});root.append(quick);\n }\n renderPhotoCatalog();stockContext();\n}\nfunction renderPhotoCatalog(){\n let root=$('product-gallery');if(!root){root=document.createElement('div');root.id='product-gallery';$('stock-list').before(root);}root.replaceChildren();\n for(const p of state.products){const card=document.createElement('div');card.className='product-photo-card';const name=document.createElement('h4');name.textContent=p.name+' / '+p.color+' / '+p.size;card.append(name);const grid=document.createElement('div');grid.className='photo-grid';for(const [n,id]of (p.images||[]).filter(validPhoto).entries())grid.append(photoThumb(id,p.name+' '+(n+1)));card.append(grid);const edit=document.createElement('button');edit.type='button';edit.className='button secondary';edit.textContent=(p.images?.length?'写真を変更':'写真を追加');edit.setAttribute('aria-label',p.name+'の写真を変更');edit.addEventListener('click',()=>{$('stock-action').value='photos';stockFields();$('stock-sku').value=p.id;$('stock-sku').dispatchEvent(new Event('change'));$('stock-fields').scrollIntoView({block:'start',behavior:'smooth'});});card.append(edit);root.append(card);}\n}\nfunction confirmationPhotos(data){\n let root=$('confirmation-photos');if(!root){root=document.createElement('div');root.id='confirmation-photos';root.className='photo-grid';$('preview-text').after(root);}root.replaceChildren();const ids=new Set();\n const scan=value=>{if(Array.isArray(value)){value.forEach(scan);return;}if(!value||typeof value!=='object')return;for(const [key,child]of Object.entries(value)){if(key==='images'){for(const id of child||[])if(validPhoto(id))ids.add(id);}else scan(child);}};\n scan(data);for(const [n,id]of [...ids].entries())root.append(photoThumb(id,'確認する商品写真 '+(n+1)));\n}\nfunction stockContext(){\n if(!state)return;const action=$('stock-action').value,sku=$('stock-sku')?.value,holder=$('stock-holder')?.value||$('stock-from')?.value,sale=state.sales.find(v=>v.id===$('stock-saleId')?.value);let note='';\n if(sku&&holder){const q=state.quantities.find(q=>q.sku===sku&&q.holder===holder);if(q)note='現物 '+q.onHand+'個 / 注文確保 '+q.reserved+'個 / 空き '+(q.onHand-q.reserved)+'個';}\n if(action==='new_product'&&$('stock-stockType')){const purchase=$('stock-stockType').value==='purchase';$('stock-amount-field').hidden=!purchase;$('stock-amount').disabled=!purchase;if(!purchase)$('stock-amount').value='0';note=purchase?'商品・入荷個数・今回の支払額をまとめて記録します。同じ仕入れを経費フォームにも入力しないでください。':'商品名・色・サイズと、いまある個数・保管者をまとめて登録します。過去の購入費は追加しません。';}\n if(action==='sale'&&$('sale-total')){const qty=Number($('stock-qty').value),price=Number($('stock-unitPrice').value);text('sale-total',qty>0&&price>0?rm(qty*Math.round(price*100)/100):'—');note+='\\n売れた個数と、今回渡した個数・受け取った金額を分けて入力します。残りは後から報告できます。';}\n if(sale)note=sale.status+'\\n注文 '+sale.qty+'個 / 受渡し '+sale.delivered+'個 / 返品 '+sale.returned+'個\\n受取済 '+rm(sale.received)+' / 返金済 '+rm(sale.refunded);\n if(action==='opening')note+='\\n初期在庫は数量のみ。過去の購入費を会計へ追加しません。';if(action==='purchase')note+='\\n商品は一覧から選択。なければ同じ画面で新しく登録できます。同じ請求のサイズ・色違いをすべて追加し、請求全体の支払額を1回だけ記録します。';if(action==='adjust')note+='\\n現物数へ合わせる差分だけを記録します。会計残高は動きません。';text('stock-context',note.trim());$('stock-context').hidden=!note.trim();\n}\nfunction fillInventory(){stockFields();const name=id=>{const p=state.products.find(p=>p.id===id);return p?p.name+' / '+p.color+' / '+p.size:id;};const holder=id=>state.holders.find(h=>h.id===id)?.name||id;table($('stock-list'),['商品','保管者','現物','注文確保','空き'],state.quantities.map(q=>[name(q.sku),holder(q.holder),q.onHand,q.reserved,q.onHand-q.reserved]));table($('sales-list'),['購入者','商品','注文数','受渡し','実入金','状況'],[...state.sales].reverse().map(v=>[v.customer,name(v.sku),v.qty,v.delivered,rm(v.received-v.refunded),v.status]));}\nfunction entry(){\n if(state.kind==='reserve'){if(!$('reserve-paid').checked)throw Error('支払い済みの確認を付けてください。');return{day:day('reserve-day'),venue:$('venue').value,parts:parts(),paidDay:day('paid-day'),cost:number('cost')};}\n if(state.kind==='settle'){if(!$('income-confirmed').checked)throw Error('実際の受取金額を確認してください。');const operation=$('settle-operation').value,cancelled=operation==='final'&&$('event-cancelled').checked;return{bookingId:$('booking').value,operation,count:operation==='final'?(cancelled?0:number('people')):undefined,unit:operation==='final'?(cancelled?25:number('participation-unit')):undefined,income:cancelled?0:number('income'),receivedDay:day('received-day'),cancelled:cancelled||undefined};}\n if(state.kind==='expense'){if(!$('expense-paid').checked)throw Error('支払い済みの確認を付けてください。');return{day:day('expense-day'),category:$('expense-category').value,merchant:$('merchant').value,description:$('expense-description').value,amount:number('expense-amount')};}\n if(photoUploads.size)throw Error('写真の保存が終わるまでお待ちください。');if(!$('stock-confirmed').checked)throw Error('数量・受け渡し・入出金を確認してください。');const action=$('stock-action').value,body={action};for(const [key,,type]of stockSchema[action]){if(type==='product'&&action==='sale')Object.assign(body,selectedProduct('stock-sku',true));else body[key]=type==='date'?day('stock-'+key):['money','qty','zeroqty'].includes(type)?number('stock-'+key):$('stock-'+key).value;}\n if(['product','new_product','photos'].includes(action))body.images=photoValues('stock-images');\n if(action==='purchase')body.lines=[...$('purchase-lines').children].map(row=>({...selectedProduct(row.id+'-sku'),holder:$(row.id+'-holder').value,qty:number(row.id+'-qty')}));return body;\n}\nasync function initialize(){if(!/^[a-fA-F0-9]{64}$/.test(token)){$('loading').hidden=true;throw Error('Google Chatで「予約」「精算」「経費」「在庫」と送って、届いた入力リンクから開いてください。');}state=await request('load');$('login').hidden=true;$('content').hidden=false;$('loading').hidden=true;const meta={reserve:['COURT RESERVATION','コート予約・支払い','支払ったコート代を、開催日と予約の内訳と一緒に残します。'],settle:['SESSION REPORT','開催後の報告・入金','予約を選び、最終人数と実際の入金を確定します。'],expense:['EXPENSE RECORD','経費を記録','購入先と内容、実際に支払った金額を残します。'],inventory:['PRODUCTS & INVENTORY','商品・在庫・販売','誰が何個保管しているか。受け渡しと入金も、ここから。']}[state.kind];if(!meta)throw Error('入力リンクを確認してください。');text('mode-label',meta[0]);text('title',meta[1]);text('description',meta[2]);for(const [section,kind]of [['reservation','reserve'],['settlement','settle'],['expense','expense'],['inventory','inventory']])$(section).hidden=state.kind!==kind;for(const id of ['reserve-day','paid-day','received-day','expense-day'])$(id).value=state.today;for(const id of ['paid-day','received-day','expense-day'])$(id).max=state.today;if(state.kind==='reserve'&&!$('parts').children.length)addPart();if(state.kind==='settle')fillBookings();if(state.kind==='inventory')fillInventory();if(state.completed)complete(state.completed);}\nfunction complete(r){$('entry-form').hidden=true;$('confirmation').hidden=true;$('success').hidden=false;text('success-text',r.summary+'\\n\\n記録時点の残高 '+rm(r.balance));text('notification-note',r.notified===false?'会計への保存は完了しました。Chat通知を確認できませんでした。この画面で再登録する必要はありません。':'記録内容と残高をGoogle Chatへ返信します。同じ内容を別のリンクから再登録しないでください。');}\n$('login-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;lock(true);clearError();try{const r=await fetch(API+'/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:$('password').value})});$('password').value='';if(!r.ok)throw Error(r.status===429?'少し待って再度お試しください。':'パスワードを確認してください。');await initialize();}catch(e){error(e);}finally{lock(false);}});\n$('entry-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;lock(true);clearError();try{const data=entry(),r=await request('preview',{data});nonce=r.nonce;text('preview-text',r.summary);confirmationPhotos(data);$('entry-form').hidden=true;$('confirmation').hidden=false;$('confirmation').scrollIntoView({block:'start',behavior:'smooth'});}catch(e){error(e);}finally{lock(false);}});\n$('commit').addEventListener('click',async()=>{if(busy||!nonce)return;lock(true);clearError();try{complete(await request('commit',{nonce}));}catch(e){error(e);}finally{lock(false);}});$('edit').addEventListener('click',()=>{nonce=null;$('confirmation').hidden=true;$('entry-form').hidden=false;});$('add-part').addEventListener('click',addPart);$('booking').addEventListener('change',bookingDetail);for(const id of ['people','participation-unit'])$(id).addEventListener('input',updateExpected);$('full-income').addEventListener('click',()=>{try{const qty=number('people'),unit=number('participation-unit');if(qty<=0||unit<=0)throw Error('人数と1人あたりの参加費を入力してください。');$('income').value=String(qty*Math.round(unit*100)/100);}catch(e){error(e);}});$('settle-operation').addEventListener('change',settlementOperation);$('stock-action').addEventListener('change',stockFields);for(const button of document.querySelectorAll('[data-stock-action]'))button.addEventListener('click',()=>{$('stock-action').value=button.dataset.stockAction;stockFields();});$('event-cancelled').addEventListener('change',settlementOperation);initialize().catch(e=>{$('loading').hidden=true;error(e);});\n})();\n</script></body></html>\n";
